export function applyMarketingCopy(landing: SeoLanding): SeoLanding {
  const override = COPY[landing.path];
  return override ? { ...landing, ...override } : landing;
}

export function hasMarketingCopy(path: string) {
  return Boolean(COPY[path]);
}

export const MARKETING_COPY_PATHS = Object.keys(COPY);
